package televibe

import (
	"context"
	"fmt"
	"log/slog"
	"sync"
	"time"

	"github.com/gravitational/teleport/api/client"
	"github.com/gravitational/teleport/api/types"
	"golang.org/x/sync/errgroup"

	"televibe/ai"
	"televibe/jira"
	"televibe/risk"
)

type App struct {
	cfg    *Config
	tele   *client.Client
	ai     ai.Provider
	jira   *jira.Client
	scorer *risk.Scorer

	pending   map[string]string
	pendingMu sync.Mutex
}

func NewApp(ctx context.Context, cfg *Config) (*App, error) {
	tele, err := client.New(ctx, client.Config{
		Addrs: []string{cfg.Teleport.Addr},
		Credentials: []client.Credentials{
			client.LoadIdentityFile(cfg.Teleport.IdentityFile),
		},
	})
	if err != nil {
		return nil, fmt.Errorf("teleport client: %w", err)
	}

	prov, err := ai.New(cfg.AI)
	if err != nil {
		return nil, fmt.Errorf("ai provider: %w", err)
	}

	jc, err := jira.New(cfg.Jira)
	if err != nil {
		return nil, fmt.Errorf("jira client: %w", err)
	}

	scorer, err := risk.NewScorer(cfg.Risk)
	if err != nil {
		return nil, fmt.Errorf("scorer: %w", err)
	}

	return &App{
		cfg:     cfg,
		tele:    tele,
		ai:      prov,
		jira:    jc,
		scorer:  scorer,
		pending: map[string]string{},
	}, nil
}

func (a *App) Run(ctx context.Context) error {
	slog.Info("televibe starting",
		"provider", a.cfg.AI.Provider,
		"threshold", a.cfg.Risk.TicketThreshold,
		"itsm_project", a.cfg.Jira.Project)

	if err := a.rehydrate(ctx); err != nil {
		return fmt.Errorf("rehydrate open ITSM tickets: %w", err)
	}

	g, gctx := errgroup.WithContext(ctx)
	g.Go(func() error { return a.watchRequests(gctx) })
	g.Go(func() error { return a.pollITSM(gctx) })
	return g.Wait()
}

func (a *App) rehydrate(ctx context.Context) error {
	open, err := a.jira.ListOpenTeleportTickets(ctx)
	if err != nil {
		return err
	}
	a.pendingMu.Lock()
	for reqID, ticket := range open {
		a.pending[reqID] = ticket
	}
	a.pendingMu.Unlock()
	slog.Info("rehydrated pending tickets", "count", len(open))
	return nil
}

func (a *App) watchRequests(ctx context.Context) error {
	watcher, err := a.tele.NewWatcher(ctx, types.Watch{
		Kinds: []types.WatchKind{{Kind: types.KindAccessRequest}},
	})
	if err != nil {
		return fmt.Errorf("start watcher: %w", err)
	}
	defer watcher.Close()

	for {
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-watcher.Done():
			return watcher.Error()
		case ev := <-watcher.Events():
			if ev.Type != types.OpPut {
				continue
			}
			req, ok := ev.Resource.(types.AccessRequest)
			if !ok {
				continue
			}
			if req.GetState() != types.RequestState_PENDING {
				continue
			}
			a.pendingMu.Lock()
			_, held := a.pending[req.GetName()]
			a.pendingMu.Unlock()
			if held {
				continue
			}
			go a.handleRequest(ctx, req)
		}
	}
}

func (a *App) handleRequest(ctx context.Context, req types.AccessRequest) {
	id := req.GetName()
	log := slog.With("request_id", id, "user", req.GetUser())

	log.Info("scoring access request")
	result, err := a.scorer.Score(ctx, a.ai, req)
	if err != nil {
		log.Error("scoring failed", "err", err)
		return
	}
	log.Info("risk scored",
		"score", result.Score,
		"tier", result.Tier.Name,
		"slang", result.Tier.Slang,
		"components", result.Components)

	if result.Score < a.cfg.Risk.TicketThreshold {
		reason := fmt.Sprintf("televibe: %s (score %d, %q) — auto-approved",
			result.Tier.Name, result.Score, result.Tier.Slang)
		if err := a.submitReview(ctx, id, types.RequestState_APPROVED, reason); err != nil {
			log.Error("auto-approve failed", "err", err)
		}
		return
	}

	ticket, err := a.jira.CreateITSMTicket(ctx, jira.TicketInput{
		RequestID:   id,
		User:        req.GetUser(),
		Roles:       req.GetRoles(),
		Reason:      req.GetRequestReason(),
		Score:       result.Score,
		Tier:        result.Tier.Name,
		Slang:       result.Tier.Slang,
		Components:  result.Components,
		AIReasoning: result.Reasoning,
	})
	if err != nil {
		log.Error("create ITSM ticket failed", "err", err)
		return
	}

	a.pendingMu.Lock()
	a.pending[id] = ticket
	a.pendingMu.Unlock()
	log.Info("ITSM ticket created, request held for SRE review",
		"ticket", ticket, "tier", result.Tier.Name, "slang", result.Tier.Slang)
}

func (a *App) pollITSM(ctx context.Context) error {
	t := time.NewTicker(a.cfg.Jira.PollInterval)
	defer t.Stop()
	for {
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-t.C:
			a.reconcileITSM(ctx)
		}
	}
}

func (a *App) reconcileITSM(ctx context.Context) {
	a.pendingMu.Lock()
	snap := make(map[string]string, len(a.pending))
	for k, v := range a.pending {
		snap[k] = v
	}
	a.pendingMu.Unlock()

	for requestID, ticket := range snap {
		status, err := a.jira.TicketStatus(ctx, ticket)
		if err != nil {
			slog.Warn("ITSM status check failed", "ticket", ticket, "err", err)
			continue
		}
		var next types.RequestState
		switch status {
		case jira.StatusApproved:
			next = types.RequestState_APPROVED
		case jira.StatusRejected:
			next = types.RequestState_DENIED
		default:
			continue
		}
		reason := fmt.Sprintf("televibe: ITSM %s resolved (%s)", ticket, status)
		if err := a.submitReview(ctx, requestID, next, reason); err != nil {
			slog.Error("submit review failed", "request_id", requestID, "err", err)
			continue
		}
		a.pendingMu.Lock()
		delete(a.pending, requestID)
		a.pendingMu.Unlock()
	}
}

func (a *App) submitReview(ctx context.Context, requestID string, state types.RequestState, reason string) error {
	_, err := a.tele.SubmitAccessReview(ctx, types.AccessReviewSubmission{
		RequestID: requestID,
		Review: types.AccessReview{
			Author:        "televibe",
			ProposedState: state,
			Reason:        reason,
		},
	})
	return err
}

package ai

import (
	"context"
	"encoding/json"
	"fmt"
	"regexp"
	"strings"
)

type Config struct {
	Provider  string          `toml:"provider"`
	Anthropic AnthropicConfig `toml:"anthropic"`
	Bedrock   BedrockConfig   `toml:"bedrock"`
	Webhook   WebhookConfig   `toml:"webhook"`
}

func (c *Config) Validate() error {
	switch c.Provider {
	case "anthropic":
		if c.Anthropic.APIKey == "" {
			return fmt.Errorf("anthropic.api_key is required")
		}
	case "bedrock":
		if c.Bedrock.Region == "" {
			return fmt.Errorf("bedrock.region is required")
		}
	case "webhook":
		if c.Webhook.URL == "" {
			return fmt.Errorf("webhook.url is required")
		}
	default:
		return fmt.Errorf("provider must be one of: anthropic, bedrock, webhook")
	}
	return nil
}

type ScoreRequest struct {
	User              string   `json:"user"`
	Roles             []string `json:"roles"`
	Resources         []string `json:"resources"`
	Reason            string   `json:"reason"`
	HasCUSTXReference bool     `json:"has_custx_reference"`
	DescriptionLength int      `json:"description_length"`
}

type Assessment struct {
	DescriptionQuality int    `json:"description_quality"`
	PrivilegeConcern   int    `json:"privilege_concern"`
	Anomalies          int    `json:"anomalies"`
	Reasoning          string `json:"reasoning"`
}

type Provider interface {
	Assess(ctx context.Context, req ScoreRequest) (*Assessment, error)
}

func New(cfg Config) (Provider, error) {
	switch cfg.Provider {
	case "anthropic":
		return NewAnthropic(cfg.Anthropic), nil
	case "bedrock":
		return NewBedrock(cfg.Bedrock)
	case "webhook":
		return NewWebhook(cfg.Webhook), nil
	}
	return nil, fmt.Errorf("unknown provider: %s", cfg.Provider)
}

const SystemPrompt = `You are a security analyst reviewing a Teleport access request.
Assess the risk of granting the requested access based on the details provided.

Return ONLY a JSON object with these exact fields (no prose, no markdown fence):
{
  "description_quality": <int 0-25; 0 = thorough and specific, 25 = absent or vague>,
  "privilege_concern": <int 0-25; 0 = routine read access, 25 = broad production admin or destructive capability>,
  "anomalies": <int 0-10; flag mismatches between stated purpose and requested scope, or other unusual patterns>,
  "reasoning": "<2-3 sentences explaining the scores>"
}

Scoring guidance:
- description_quality: does the reason describe WHAT work will be performed and WHY, and does the scope match the work described?
- privilege_concern: how large is the blast radius of the requested roles and resources? Production prod-*, root, admin, or destructive tooling score higher.
- anomalies: scope/purpose mismatch, vague intent, requests outside the user's typical pattern, off-hours emergency without justification.`

func UserPrompt(req ScoreRequest) string {
	var sb strings.Builder
	sb.WriteString("Access request details:\n\n")
	fmt.Fprintf(&sb, "User: %s\n", req.User)
	fmt.Fprintf(&sb, "Requested roles: %s\n", strings.Join(req.Roles, ", "))
	if len(req.Resources) > 0 {
		fmt.Fprintf(&sb, "Requested resources: %s\n", strings.Join(req.Resources, ", "))
	}
	fmt.Fprintf(&sb, "Contains CUSTX ticket reference: %v\n", req.HasCUSTXReference)
	fmt.Fprintf(&sb, "Description length: %d characters\n\n", req.DescriptionLength)
	sb.WriteString("Request reason (verbatim):\n")
	sb.WriteString("---\n")
	sb.WriteString(req.Reason)
	sb.WriteString("\n---\n\nReturn the JSON assessment.")
	return sb.String()
}

var jsonRE = regexp.MustCompile(`(?s)\{.*\}`)

func parseAssessment(text string) (*Assessment, error) {
	m := jsonRE.FindString(text)
	if m == "" {
		return nil, fmt.Errorf("no JSON object in model output: %q", text)
	}
	var a Assessment
	if err := json.Unmarshal([]byte(m), &a); err != nil {
		return nil, fmt.Errorf("parse assessment: %w (raw: %q)", err, m)
	}
	return &a, nil
}

package ai

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
)

type AnthropicConfig struct {
	APIKey string `toml:"api_key"`
	Model  string `toml:"model"`
}

type Anthropic struct {
	cfg    AnthropicConfig
	client *http.Client
}

func NewAnthropic(cfg AnthropicConfig) *Anthropic {
	if cfg.Model == "" {
		cfg.Model = "claude-sonnet-4-6"
	}
	return &Anthropic{cfg: cfg, client: &http.Client{}}
}

func (a *Anthropic) Assess(ctx context.Context, req ScoreRequest) (*Assessment, error) {
	body, err := json.Marshal(map[string]any{
		"model":      a.cfg.Model,
		"max_tokens": 1024,
		"system": []map[string]any{
			{
				"type":          "text",
				"text":          SystemPrompt,
				"cache_control": map[string]string{"type": "ephemeral"},
			},
		},
		"messages": []map[string]any{
			{"role": "user", "content": UserPrompt(req)},
		},
	})
	if err != nil {
		return nil, err
	}
	httpReq, err := http.NewRequestWithContext(ctx, http.MethodPost,
		"https://api.anthropic.com/v1/messages", bytes.NewReader(body))
	if err != nil {
		return nil, err
	}
	httpReq.Header.Set("Content-Type", "application/json")
	httpReq.Header.Set("x-api-key", a.cfg.APIKey)
	httpReq.Header.Set("anthropic-version", "2023-06-01")

	resp, err := a.client.Do(httpReq)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	if resp.StatusCode >= 300 {
		raw, _ := io.ReadAll(resp.Body)
		return nil, fmt.Errorf("anthropic %d: %s", resp.StatusCode, raw)
	}
	var out struct {
		Content []struct {
			Text string `json:"text"`
			Type string `json:"type"`
		} `json:"content"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
		return nil, err
	}
	for _, c := range out.Content {
		if c.Type == "text" {
			return parseAssessment(c.Text)
		}
	}
	return nil, fmt.Errorf("no text content in anthropic response")
}

package ai

import (
	"context"
	"encoding/json"
	"fmt"

	"github.com/aws/aws-sdk-go-v2/aws"
	awsconfig "github.com/aws/aws-sdk-go-v2/config"
	"github.com/aws/aws-sdk-go-v2/service/bedrockruntime"
)

type BedrockConfig struct {
	Region  string `toml:"region"`
	ModelID string `toml:"model_id"`
}

type Bedrock struct {
	cfg    BedrockConfig
	client *bedrockruntime.Client
}

func NewBedrock(cfg BedrockConfig) (*Bedrock, error) {
	if cfg.ModelID == "" {
		cfg.ModelID = "us.anthropic.claude-sonnet-4-6-v1:0"
	}
	awsCfg, err := awsconfig.LoadDefaultConfig(context.Background(), awsconfig.WithRegion(cfg.Region))
	if err != nil {
		return nil, fmt.Errorf("aws config: %w", err)
	}
	return &Bedrock{cfg: cfg, client: bedrockruntime.NewFromConfig(awsCfg)}, nil
}

func (b *Bedrock) Assess(ctx context.Context, req ScoreRequest) (*Assessment, error) {
	body, err := json.Marshal(map[string]any{
		"anthropic_version": "bedrock-2023-05-31",
		"max_tokens":        1024,
		"system":            SystemPrompt,
		"messages": []map[string]any{
			{"role": "user", "content": UserPrompt(req)},
		},
	})
	if err != nil {
		return nil, err
	}
	out, err := b.client.InvokeModel(ctx, &bedrockruntime.InvokeModelInput{
		ModelId:     aws.String(b.cfg.ModelID),
		ContentType: aws.String("application/json"),
		Accept:      aws.String("application/json"),
		Body:        body,
	})
	if err != nil {
		return nil, fmt.Errorf("bedrock invoke: %w", err)
	}
	var parsed struct {
		Content []struct {
			Text string `json:"text"`
			Type string `json:"type"`
		} `json:"content"`
	}
	if err := json.Unmarshal(out.Body, &parsed); err != nil {
		return nil, fmt.Errorf("bedrock decode: %w", err)
	}
	for _, c := range parsed.Content {
		if c.Type == "text" {
			return parseAssessment(c.Text)
		}
	}
	return nil, fmt.Errorf("no text content in bedrock response")
}

package ai

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
)

type WebhookConfig struct {
	URL        string            `toml:"url"`
	AuthHeader string            `toml:"auth_header"`
	Headers    map[string]string `toml:"headers"`
}

type Webhook struct {
	cfg    WebhookConfig
	client *http.Client
}

func NewWebhook(cfg WebhookConfig) *Webhook {
	return &Webhook{cfg: cfg, client: &http.Client{}}
}

type webhookPayload struct {
	SystemPrompt string       `json:"system_prompt"`
	UserPrompt   string       `json:"user_prompt"`
	Request      ScoreRequest `json:"request"`
}

func (w *Webhook) Assess(ctx context.Context, req ScoreRequest) (*Assessment, error) {
	body, err := json.Marshal(webhookPayload{
		SystemPrompt: SystemPrompt,
		UserPrompt:   UserPrompt(req),
		Request:      req,
	})
	if err != nil {
		return nil, err
	}
	httpReq, err := http.NewRequestWithContext(ctx, http.MethodPost, w.cfg.URL, bytes.NewReader(body))
	if err != nil {
		return nil, err
	}
	httpReq.Header.Set("Content-Type", "application/json")
	if w.cfg.AuthHeader != "" {
		httpReq.Header.Set("Authorization", w.cfg.AuthHeader)
	}
	for k, v := range w.cfg.Headers {
		httpReq.Header.Set(k, v)
	}
	resp, err := w.client.Do(httpReq)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	if resp.StatusCode >= 300 {
		raw, _ := io.ReadAll(resp.Body)
		return nil, fmt.Errorf("webhook %d: %s", resp.StatusCode, raw)
	}
	var a Assessment
	if err := json.NewDecoder(resp.Body).Decode(&a); err != nil {
		return nil, fmt.Errorf("webhook decode: %w", err)
	}
	return &a, nil
}

package risk

type Config struct {
	TicketThreshold int    `toml:"ticket_threshold"`
	CUSTXPattern    string `toml:"custx_pattern"`
	OffHoursStart   int    `toml:"off_hours_start"`
	OffHoursEnd     int    `toml:"off_hours_end"`
	Timezone        string `toml:"timezone"`
}

func (c *Config) ApplyDefaults() {
	if c.TicketThreshold == 0 {
		c.TicketThreshold = 25
	}
	if c.CUSTXPattern == "" {
		c.CUSTXPattern = `CUSTX-\d+`
	}
	if c.Timezone == "" {
		c.Timezone = "UTC"
	}
}

type Tier struct {
	Name     string
	Slang    string
	MinScore int
}

var Tiers = []Tier{
	{Name: "low", Slang: "no cap", MinScore: 0},
	{Name: "medium", Slang: "sus", MinScore: 25},
	{Name: "high", Slang: "mad sus fr", MinScore: 50},
	{Name: "critical", Slang: "straight L, touch grass", MinScore: 75},
}

func TierForScore(score int) Tier {
	chosen := Tiers[0]
	for _, t := range Tiers {
		if score >= t.MinScore {
			chosen = t
		}
	}
	return chosen
}

